import sys

def count_unique(array, start_idx, end_idx):
    seen_colors = [False] * 24
    unique_count = 0
    for i in range(start_idx, end_idx + 1):
        color = array[i]
        if not seen_colors[color]:
            seen_colors[color] = True
            unique_count += 1
    return unique_count

def main():
    input_line = sys.stdin.readline().strip()
    a, b, l, r = map(int, input_line.split())
    l -= 1
    r -= 1
    total_ab = a + b
    repeat_times = 4
    pattern_arr = [0] * (total_ab * repeat_times)
    shift_h = l // total_ab
    l -= shift_h * total_ab
    r -= shift_h * total_ab
    segment_size = (r - l + 1) // total_ab
    if segment_size > 2:
        r -= (segment_size - 2) * total_ab
    delta_val = max(a - b, 1)
    for rep_idx in range(repeat_times):
        for k in range(a - delta_val):
            pattern_arr[total_ab * rep_idx + k] = k
        for k in range(delta_val):
            pattern_arr[total_ab * rep_idx + a - delta_val + k] = (a - delta_val + k) if (rep_idx % 2 == 0) else (a + k)
    min_colors_needed = a + a
    for shift_a_idx in range(1, delta_val + 1):
        for k in range(b):
            pattern_arr[a + k] = pattern_arr[a - shift_a_idx]
        for shift_b_idx1 in range(1, delta_val + 1):
            for k in range(b):
                pattern_arr[total_ab + a + k] = pattern_arr[total_ab + a - shift_b_idx1]
            for shift_b_idx2 in range(1, delta_val + 1):
                for k in range(b):
                    pattern_arr[2 * total_ab + a + k] = pattern_arr[2 * total_ab + a - shift_b_idx2]
                for shift_b_idx3 in range(1, delta_val + 1):
                    for k in range(b):
                        pattern_arr[3 * total_ab + a + k] = pattern_arr[3 * total_ab + a - shift_b_idx3]
                    min_colors_needed = min(min_colors_needed, count_unique(pattern_arr, l, r))
    print(min_colors_needed)

if __name__ == "__main__":
    main()

